import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import './Resources.css';

const ResourcesPage = () => {
  
  // --- 1. ADVANCED SCROLL OBSERVER ---
  useEffect(() => {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
        }
      });
    }, { threshold: 0.1, rootMargin: "0px 0px -50px 0px" });

    const elements = document.querySelectorAll('.reveal-on-scroll');
    elements.forEach(el => observer.observe(el));
    return () => observer.disconnect();
  }, []);

  // --- 2. STATIC DATA (Patents, Papers, Training) ---
  const publications = [
    { type: 'Conference Paper', title: 'Comparative Analysis of RNN models for Air Pollution Forecasting', venue: 'ICICDS-2025', status: 'Published' },
    { type: 'Research Paper', title: 'A Comparative Analysis of Conventional Methods for Sensor-Driven Spatial Interpolation', venue: 'Eng. Tech & Applied Science Research', status: 'Communicated' },
    { type: 'Conference Paper', title: 'AI-Based Environmental Pollution Monitoring with Personalized Health Risk Assessment', venue: 'ICSSAI-2025 (Kolkata)', status: 'Accepted' }
  ];

  const patent = {
    title: 'AI Integrated Water Level Monitoring Solution with Flood Alerts',
    appNumber: '202441079490',
    filingDate: 'October 25, 2024',
    status: 'Filed with INDIA Patent Office'
  };

  const trainingEvents = [
    { title: 'IoT Impression – Arduino & RPi', type: 'Workshop', duration: '1 Day', date: 'March 19, 2025', participants: 40 },
    { title: 'Electronic Prototyping & IoT', type: 'Internship', duration: '15 Days', date: 'June 2-24, 2025', participants: '49 (9 Teams)' },
    { title: 'IoT Powered Robotics', type: 'Workshop', duration: '3 Days', date: 'June 25-27, 2025', participants: 37 },
    { title: 'IoT Prototyping and PCB Design', type: 'VAC', duration: '4 Days', date: 'July 1-4, 2025', participants: 63 },
    { title: 'Edge Hardware Design', type: 'Workshop', duration: '10 Days', date: 'July 7-17, 2025', participants: 84 },
    { title: 'Embedded System Design', type: 'VAC', duration: '5 Days', date: 'July 16-21, 2025', participants: 51 },
    { title: 'Raspberry Pi Workshop', type: 'Workshop', duration: '1 Day', date: 'Sept 11, 2025', participants: 63 }
  ];

  const objectives = [
    "Develop intelligent sensor modules for pollution monitoring.",
    "Validate smart water level monitoring with flood alerts.",
    "Create digital systems for water level distribution.",
    "Build a startup & skill development ecosystem.",
    "Develop Explainable AI (XAI) analysis software for IoT."
  ];

  // --- 3. BROCHURE FETCH + FALLBACK LOGIC ---
  const [brochures, setBrochures] = useState([]);
  const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://127.0.0.1:8000';

  useEffect(() => {
    // Defines backup data in case API fails
    const fallbackBrochures = [
        { title: "Project Brochure 2025", description: "Overview of AI-IoT Innovations.", category: "General", url: "#" },
        { title: "IoT Internship Syllabus", description: "Course structure for Summer 2025.", category: "Training", url: "#" },
        { title: "Sensor Specs Sheet", description: "Technical details of AQMS modules.", category: "Technical", url: "#" }
    ];

    const fetchBrochures = async () => {
      try {
        const response = await fetch(`${API_BASE_URL}/api/brochures/`);
        if (!response.ok) throw new Error('Network response was not ok');
        const data = await response.json();
        const brochureArray = data.results || data;

        if (brochureArray && brochureArray.length > 0) {
          setBrochures(brochureArray.map(b => ({
            title: b.title,
            description: b.description,
            url: b.file.startsWith('http') ? b.file : `${API_BASE_URL}${b.file}`,
            category: b.category || 'Doc'
          })));
        } else {
            // API returned empty list, use fallback
            setBrochures(fallbackBrochures);
        }
      } catch (error) {
        console.warn('API fetch failed, using fallback data:', error);
        setBrochures(fallbackBrochures);
      }
    };
    fetchBrochures();
  }, [API_BASE_URL]);

  return (
    <div className="resources-page-container">
      
      {/* Header */}
      <nav className="aiiot-header-local">
        <div className="nav-container-inner">
           <Link to="/" style={{ textDecoration: 'none' }}>
             <span className="logo-text">AI-IoT Innovations</span>
           </Link>
           <div className="desktop-nav" style={{ display: 'flex', alignItems: 'center' }}>
             <a href="https://aiiot.it.com/project/intelligent-sensor" className="nav-link">Solutions</a>
             <Link to="/resources" className="nav-link active">Resources</Link>
             <Link to="/contact" className="nav-link">Contact</Link>
           </div>
        </div>
      </nav>

      <div className="resources-content-wrapper">
        
        {/* Hero */}
        <section className="resources-hero-section reveal-on-scroll">
          <span className="hero-badge">Center of Excellence</span>
          <h1 className="page-title">Innovation <span className="text-gradient">Unlimited</span></h1>
          <p className="page-intro">
            Pioneering digital networking for preventive environmental monitoring and smart city infrastructure.
          </p>

          <div className="objectives-grid">
            {objectives.map((obj, i) => (
                <div key={i} className="objective-card reveal-on-scroll delay-100">
                    <p style={{ margin: 0, color: '#e2e8f0' }}>✅ {obj}</p>
                </div>
            ))}
          </div>
        </section>

        {/* IP Section */}
        <div className="section-header reveal-on-scroll">
            <h2 className="section-title">Patents & Research</h2>
            <span className="section-subtitle">Intellectual Property Portfolio</span>
        </div>

        <div className="tech-grid">
             {/* Patent */}
             <div className="tech-card reveal-on-scroll delay-100" style={{ borderLeft: '4px solid #f97316' }}>
                <span className="status-pill pill-orange">Patent Filed</span>
                <h3 className="card-title">{patent.title}</h3>
                <div className="card-venue">
                    App: {patent.appNumber}<br/>
                    Date: {patent.filingDate}
                </div>
                <div style={{ marginTop: 'auto', fontSize: '0.85rem', color: '#fb923c' }}>
                    Status: {patent.status}
                </div>
             </div>

             {/* Publications */}
             {publications.map((pub, idx) => (
                <div key={idx} className={`tech-card reveal-on-scroll delay-${(idx+2)*100}`}>
                    <span className={`status-pill ${pub.status === 'Published' || pub.status === 'Accepted' ? 'pill-green' : 'pill-blue'}`}>
                        {pub.status}
                    </span>
                    <h3 className="card-title">{pub.title}</h3>
                    <div className="card-venue">{pub.venue}</div>
                    <div style={{ marginTop: 'auto', fontSize: '0.85rem', color: '#64748b' }}>
                        {pub.type}
                    </div>
                </div>
             ))}
        </div>

        {/* Training Section */}
        <div className="section-header reveal-on-scroll">
            <h2 className="section-title">Manpower & Workshops</h2>
            <span className="section-subtitle">Skill Development Statistics (2025)</span>
        </div>

        <div className="dark-table-wrapper reveal-on-scroll delay-100">
            <table className="dark-table">
                <thead>
                    <tr>
                        <th>Program Title</th>
                        <th>Type</th>
                        <th>Duration</th>
                        <th>Date</th>
                        <th>Participants</th>
                    </tr>
                </thead>
                <tbody>
                    {trainingEvents.map((ev, i) => (
                        <tr key={i}>
                            <td style={{ fontWeight: 600, color: '#fff' }}>{ev.title}</td>
                            <td><span style={{ background: 'rgba(255,255,255,0.1)', padding: '2px 8px', borderRadius: '4px', fontSize: '0.8rem' }}>{ev.type}</span></td>
                            <td>{ev.duration}</td>
                            <td>{ev.date}</td>
                            <td>{ev.participants}</td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>

        {/* Downloads / Brochures */}
        <div className="section-header reveal-on-scroll">
            <h2 className="section-title">Resources Download</h2>
            <span className="section-subtitle">Access technical documents and brochures</span>
        </div>

        <div className="brochure-grid">
            {brochures.map((b, idx) => (
                <div key={idx} className="brochure-item reveal-on-scroll delay-200">
                    <div className="icon-box">📄</div>
                    <div className="brochure-title">{b.title}</div>
                    <div style={{ fontSize: '0.85rem', color: '#94a3b8' }}>{b.description}</div>
                    <a href={b.url} className="download-text">
                        Download PDF <span>↓</span>
                    </a>
                </div>
            ))}
        </div>

        <div style={{ marginTop: '6rem', textAlign: 'center', opacity: 0.6 }}>
            <Link to="/" style={{ color: '#fff', textDecoration: 'none' }}>← Back to Home</Link>
        </div>

      </div>
    </div>
  );
};

export default ResourcesPage;
